class TTLCache:
    def __init__(self, clock, ttl):
        self.clock = clock
        self.ttl = ttl
        self._data = {}

    def get(self, key, default=None):
        hit = self._data.get(key)
        if hit is None:
            return default
        stored_at, value = hit
        if self.clock.time() - stored_at >= self.ttl:
            del self._data[key]
            return default
        return value

    def put(self, key, value):
        self._data[key] = (self.clock.time(), value)

    def drop(self, key):
        self._data.pop(key, None)

